exec('import pandas as pd\nimport json\nimport pandas as pd\nimport json\nFEATURE_NAMES = ("feature_1", "feature_2")\nclass FrozenPreprocessor:\n    def transform(self, values):\n        return [[float(x) for x in row] for row in values]\nclass FrozenModel:\n    def predict(self, values):\n        return [row[0] + 2.0 * row[1] for row in values]\npreprocessing_pipeline = FrozenPreprocessor()\nmodel = FrozenModel()\nclass FittedPackage:\n    def predict(self, values):\n        return model.predict(preprocessing_pipeline.transform(values))\nfitted_package = FittedPackage()\ncontract = {\'fixture_only\': True, \'domain\': \'anonymous two-feature orders\', \'feature_names\': [\'feature_1\', \'feature_2\'], \'request_keys\': [\'features\'], \'response_keys\': [\'predictions\', \'version\'], \'matrix_rank\': 2, \'matrix_width\': 2, \'feature_min\': 0.0, \'feature_max\': 10.0, \'limits_inclusive\': True, \'numpy_dtype\': \'float64\', \'prediction_rows\': \'one per request row\', \'batch_key\': \'order_id\', \'batch_result_keys\': [\'order_id\', \'prediction\', \'version\'], \'chunk_size\': 2, \'batch_input_path\': \'orders.csv\', \'batch_output_path\': \'learner_results.jsonl\', \'host\': \'127.0.0.1\', \'port\': 8080, \'prediction_route\': \'/predict\', \'readiness_route\': \'/ping\', \'success_status\': 200, \'schema_rejection_status\': 400, \'denied_status\': 403, \'not_ready_status\': 503, \'ready_payload\': {\'ready\': True}, \'not_ready_payload\': {\'ready\': False}, \'timeout_seconds\': 2.0, \'healthcheck\': {\'command\': [\'CMD\', \'python\', \'health_probe.py\'], \'interval_seconds\': 5, \'timeout_seconds\': 2, \'retries\': 3}, \'version\': \'A\', \'expected_request\': {\'features\': [[1.0, 2.0], [2.0, 3.0], [3.0, 4.0]]}, \'expected_response\': {\'predictions\': [5.0, 8.0, 11.0], \'version\': \'A\'}, \'expected_audience\': \'order-prediction-fixture\', \'permitted_subjects\': [\'fixture-subject-permitted\'], \'credential_secret_reference\': \'credential\', \'injected_secret_variable\': \'ORDER_FIXTURE_CREDENTIAL\', \'logging_policy\': \'Record failure class only; never record token, credential literal or protected request values.\'}\ndef supplied_failure_fixtures(decoded):\n    return [decoded[:-1], decoded + decoded[:1], [dict(r, order_id=\'unknown\') if i == 0 else r for i,r in enumerate(decoded)], [dict(r, prediction=\'malformed\') if i == 0 else r for i,r in enumerate(decoded)]]\nimport builtins\nreal_open = builtins.open\nreal_read_csv = pd.read_csv\nio_events = []\nclass ObservedOutput:\n    def __init__(self, handle):\n        self.handle = handle\n    def __enter__(self):\n        self.handle.__enter__()\n        return self\n    def __exit__(self, *args):\n        return self.handle.__exit__(*args)\n    def write(self, value):\n        result = self.handle.write(value)\n        io_events.append((\'write\', value))\n        return result\n    def flush(self):\n        return self.handle.flush()\ndef observed_open(path, mode=\'r\', *args, **kwargs):\n    handle = real_open(path, mode, *args, **kwargs)\n    if path == contract[\'batch_output_path\'] and mode == \'w\':\n        return ObservedOutput(handle)\n    return handle\ndef observed_read_csv(handle, *args, **kwargs):\n    result = real_read_csv(handle, *args, **kwargs)\n    if \'chunksize\' not in kwargs:\n        return result\n    def chunks():\n        for chunk in result:\n            io_events.append((\'read\', len(chunk)))\n            yield chunk\n    return chunks()\nbuiltins.open = observed_open\npd.read_csv = observed_read_csv\n\ndef supplied_numeric_prediction(value):\n    return isinstance(value, (int, float))\ndef supplied_feature_values(chunk, names):\n    return chunk[names].values.tolist()\n\ndef assert_batch_output(records, expected, contract):\n    keys = []\n    for record in records:\n        assert (set(record) == set(contract[\'batch_result_keys\']))\n        assert (supplied_numeric_prediction(record[\'prediction\']))\n        assert (record[\'version\'] == contract[\'version\'])\n        keys.append(record[contract[\'batch_key\']])\n    assert (len(keys) == len(set(keys)))\n    assert (sorted(keys) == sorted(expected))\n\ndef predict_batch(contract, fitted_package):\n    expected_keys = []\n    chunk_sizes = []\n    writes_before_next_read = []\n    with open(contract[\'batch_input_path\']) as handle:\n        with open(contract[\'batch_output_path\'], \'w\') as output:\n            for chunk in pd.read_csv(handle, chunksize=contract[\'chunk_size\']):\n                keys = []\n                for key in chunk[contract[\'batch_key\']]:\n                    keys.append(key)\n                predictions = prediction_package.predict(supplied_feature_values(chunk, contract[\'feature_names\']))\n                assert (len(predictions) == len(keys))\n                chunk_sizes.append(len(keys))\n                for key, prediction in zip(keys, predictions):\n                    record = {contract[\'batch_key\']: key, \'prediction\': prediction, \'version\': contract[\'version\']}\n                    output.write(json.dumps(record) + \'\\n\')\n                    expected_keys.append(key)\n                writes_before_next_read.append(len(keys))\n    with open(contract[\'batch_output_path\']) as handle:\n        decoded = []\n        for line in handle:\n            decoded.append(json.loads(line))\n    assert_batch_output(decoded, expected_keys, contract)\n    failures_detected = []\n    for bad in supplied_failure_fixtures(decoded):\n        try:\n            assert_batch_output(bad, expected_keys, contract)\n            failures_detected.append(False)\n        except AssertionError:\n            failures_detected.append(True)\n    for detected in failures_detected:\n        assert (detected)\n    return {\'records\': decoded, \'chunk_sizes\': chunk_sizes, \'writes_before_next_read\': writes_before_next_read, \'failures_detected\': failures_detected}')
